/// KhataPro · differential test for the hand-written crypto primitives.
///
/// The SHA-256, HMAC-SHA256, PBKDF2 and HKDF in `lib/core/security/hasher.dart`
/// and `kdf.dart` are written from the specs, with no package dependency. This
/// tool checks them against vectors generated by Python's `hashlib`/`hmac` —
/// an independent implementation — plus the published RFC vectors.
///
/// Why this exists: a single wrong constant in SHA-256 produces a *working*
/// hash that is simply not SHA-256. Every wrapped key, every audit-chain link
/// and every backup manifest would still verify against itself, so nothing in
/// the app would ever notice. A differential test is the only thing that
/// catches it.
///
///   dart run tool/crypto_verify.dart            # all groups
///   dart run tool/crypto_verify.dart --quiet    # exit code only
library;

import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import '../lib/core/security/hasher.dart';
import '../lib/core/security/kdf.dart';

int _passed = 0;
final List<String> _failures = <String>[];
bool _quiet = false;

void main(List<String> args) {
  _quiet = args.contains('--quiet');
  final path = args.firstWhere(
    (a) => !a.startsWith('--'),
    orElse: () => 'assets/testdata/crypto_vectors.json',
  );
  final file = File(path);
  if (!file.existsSync()) {
    stderr.writeln('vector file not found: $path (run from the project root, or pass a path)');
    exit(2);
  }
  final vectors = jsonDecode(file.readAsStringSync()) as Map<String, dynamic>;

  print('');
  print('  KhataPro · crypto primitives vs Python hashlib/hmac');
  print('  vectors: ${file.path} (${vectors['generated_by']})');
  print('  ${'─' * 72}');

  _section('SHA-256 — FIPS 180-4 incl. the 55/56/63/64/65-byte padding boundaries', () {
    for (final case_ in (vectors['sha256'] as List).cast<Map<String, dynamic>>()) {
      final input = _unhex(case_['hex'] as String);
      final expected = case_['digest'] as String;
      final actual = sha256Hex(input);
      _check('${case_['name']}', actual == expected,
          detail: actual == expected ? null : 'expected $expected, got $actual');
    }
    // Streaming must equal one-shot for every possible chunk split.
    final bytes = Uint8List.fromList(List.generate(300, (i) => (i * 37) & 0xFF));
    final oneShot = sha256Hex(bytes);
    for (final chunk in [1, 7, 63, 64, 65, 128, 299]) {
      final hasher = Sha256();
      for (var offset = 0; offset < bytes.length; offset += chunk) {
        hasher.update(Uint8List.sublistView(
            bytes, offset, (offset + chunk).clamp(0, bytes.length)));
      }
      _check('streaming (${chunk}-byte chunks) == one-shot',
          _toHex(hasher.digest()) == oneShot);
    }
  });

  _section('HMAC-SHA256 — RFC 4231 cases 1–7', () {
    for (final case_ in (vectors['hmac_sha256'] as List).cast<Map<String, dynamic>>()) {
      final key = _unhex(case_['key_hex'] as String);
      final msg = _unhex(case_['msg_hex'] as String);
      final expected = case_['digest'] as String;
      final actual = _toHex(HmacSha256(key: key).compute(msg));
      _check('${case_['name']}', actual == expected,
          detail: actual == expected ? null : 'expected $expected, got $actual');
    }
  });

  _section('PBKDF2-HMAC-SHA256 — RFC published vectors', () {
    for (final case_ in (vectors['pbkdf2_sha256'] as List).cast<Map<String, dynamic>>()) {
      final password = case_['password'] as String;
      final salt = _unhex(case_['salt_hex'] as String);
      final iterations = case_['iterations'] as int;
      final keyLength = case_['key_length'] as int;
      final derived = pbkdf2(
        password: password,
        salt: salt,
        iterations: iterations,
        keyLength: keyLength,
        // The vectors use Latin-1 for the embedded NUL cases.
        utf8Password: false,
      );
      final actual = _toHex(derived);
      final expected = case_['derived'] as String;
      _check('${iterations}× → ${keyLength} B', actual == expected,
          detail: actual == expected ? null : 'expected $expected, got $actual');
    }
  });

  _section('HKDF-SHA256 — RFC 5869 cases 1–3 (subkey separation)', () {
    for (final case_ in (vectors['hkdf_sha256'] as List).cast<Map<String, dynamic>>()) {
      final okm = hkdfSha256(
        ikm: _unhex(case_['ikm_hex'] as String),
        salt: _unhex(case_['salt_hex'] as String),
        info: _unhex(case_['info_hex'] as String),
        length: case_['length'] as int,
      );
      final actual = _toHex(okm);
      final expected = case_['okm'] as String;
      _check('${case_['name']}', actual == expected,
          detail: actual == expected ? null : 'expected $expected, got $actual');
    }

    // The property that matters in production: the four purposes this app
    // expands the DEK into must be mutually unrecoverable.
    final dek = _unhex('00112233445566778899aabbccddeeff00112233445566778899aabbccddeeff');
    final keys = {
      for (final purpose in KeyPurpose.values) purpose: deriveSubkey(dek, purpose),
    };
    final distinct = keys.values.map(_toHex).toSet();
    _check('one DEK expands into ${KeyPurpose.values.length} distinct subkeys',
        distinct.length == KeyPurpose.values.length);
    _check('a backup subkey gives nothing about the database subkey',
        !_containsSubsequence(keys[KeyPurpose.database]!, keys[KeyPurpose.backupPacks]!));
  });

  _section('Encodings — base64 / base64url / strict UTF-8', () {
    for (final case_ in (vectors['base64'] as List).cast<Map<String, dynamic>>()) {
      final raw = _unhex(case_['raw_hex'] as String);
      _check('std b64 (${raw.length} B)', base64Std(raw) == case_['std'],
          detail: '${base64Std(raw)} vs ${case_['std']}');
      _check('url b64 no-pad (${raw.length} B)', base64UrlNoPad(raw) == case_['url_nopad'],
          detail: '${base64UrlNoPad(raw)} vs ${case_['url_nopad']}');
    }
    // UTF-8, including the multi-byte scripts this app must handle.
    const strings = {
      '': '',
      'abc': '616263',
      'Pakistan': '50616b697374616e',
      'لاہور': 'd984d8a7db81d988d8b1',
      'اردو': 'd8a7d8b1d8afd988',
      '字': 'e5ad97',
      '₹': 'e282b9',
      '😀': 'f09f9880', // outside the BMP: surrogate pair handling
    };
    for (final entry in strings.entries) {
      _check('utf8("${entry.key}")', _toHex(utf8Encode(entry.key)) == entry.value,
          detail: '${_toHex(utf8Encode(entry.key))} vs ${entry.value}');
    }
    var threw = false;
    try {
      utf8Encode('ab\uD800cd'); // lone high surrogate
    } on ArgumentError {
      threw = true;
    }
    _check('a lone surrogate throws rather than silently mangling a passphrase', threw);

    // Round-trip through the platform decoder as an independent check.
    for (final entry in strings.entries) {
      _check('utf8Encode("${entry.key}") round-trips via dart:convert',
          utf8.decode(utf8Encode(entry.key)) == entry.key);
    }
  });

  _section('Constant-time comparison', () {
    final a = List<int>.generate(32, (i) => i);
    final b = List<int>.generate(32, (i) => i);
    final c = List<int>.generate(32, (i) => i)..[31] ^= 0x01;
    _check('equal keys compare equal', constantTimeEquals(a, b));
    _check('a one-bit difference is detected', !constantTimeEquals(a, c));
    _check('different lengths are not equal', !constantTimeEquals(a, [1, 2, 3]));
    _check('the KDF implementation agrees',
        const Pbkdf2KeyDerivation().constantTimeEquals(a, b) &&
            !const Pbkdf2KeyDerivation().constantTimeEquals(a, c));
  });

  print('');
  if (_failures.isEmpty) {
    print('  ✓ all $_passed checks passed');
    print('');
  } else {
    print('  ✗ ${_failures.length} of ${_passed + _failures.length} checks FAILED');
    for (final failure in _failures) {
      print('      · $failure');
    }
    print('');
    exitCode = 1;
  }
}

void _section(String title, void Function() body) {
  _quiet ? null : print('\n  $title');
  body();
}

void _check(String what, bool condition, {String? detail}) {
  if (condition) {
    _passed++;
    _quiet ? null : print('    ✓ $what');
  } else {
    _failures.add(detail == null ? what : '$what — $detail');
    _quiet ? null : print('    ✗ $what${detail == null ? '' : ' — $detail'}');
  }
}

Uint8List _unhex(String hex) {
  final out = Uint8List(hex.length ~/ 2);
  for (var i = 0; i < out.length; i++) {
    out[i] = int.parse(hex.substring(i * 2, i * 2 + 2), radix: 16);
  }
  return out;
}

String _toHex(List<int> bytes) {
  final buffer = StringBuffer();
  for (final byte in bytes) {
    buffer.write(byte.toRadixString(16).padLeft(2, '0'));
  }
  return buffer.toString();
}

bool _containsSubsequence(List<int> haystack, List<int> needle) {
  if (needle.length > haystack.length) return false;
  for (var i = 0; i <= haystack.length - needle.length; i++) {
    var match = true;
    for (var j = 0; j < needle.length; j++) {
      if (haystack[i + j] != needle[j]) {
        match = false;
        break;
      }
    }
    if (match) return true;
  }
  return false;
}
